/* ============================================================
   PATCH v1.4.8 — карточка задачи: sticky шапка и футер
   ============================================================ */

#taskCardModal .modal-content {
    padding: 0 !important;
    overflow-x: hidden !important;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: rgba(245,215,110,0.45) rgba(128,128,128,0.10);
}

/* Шапка — sticky top, edge-to-edge */
#taskCardModal #taskCardHead {
    position: sticky !important;
    top: 0 !important;
    z-index: 5 !important;
    margin: 0 !important;
    padding: 18px 22px 12px !important;
    background: var(--trk-modal-bg, #141414) !important;
    border-bottom: 1px solid var(--trk-card-border, rgba(245,215,110,0.15)) !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.18);
}

/* Футер — sticky bottom, edge-to-edge */
#taskCardModal .modal-actions {
    position: sticky !important;
    bottom: 0 !important;
    z-index: 5 !important;
    margin: 0 !important;
    padding: 12px 22px 18px !important;
    background: var(--trk-modal-bg, #141414) !important;
    border-top: 1px solid var(--trk-card-border, rgba(245,215,110,0.15)) !important;
    box-shadow: 0 -2px 8px rgba(0,0,0,0.18);
    display: flex !important;
    justify-content: flex-end !important;
    flex-wrap: wrap !important;
    gap: 10px !important;
}

/* Средние элементы — отступ 22px от краёв, как был padding у .modal-content */
#taskCardModal .modal-content > *:not(#taskCardHead):not(.modal-actions) {
    margin-left: 22px !important;
    margin-right: 22px !important;
}
#taskCardModal .modal-content > #taskCardHead + * {
    margin-top: 14px !important;
}

/* Внутренний скролл списка сотрудников — отключаем, скроллится вся модалка */
#taskCardModal #taskCardEmployees {
    max-height: none !important;
    overflow-y: visible !important;
    overflow-x: visible !important;
}

/* Скроллбар основного контейнера */
#taskCardModal .modal-content::-webkit-scrollbar { width: 10px; }
#taskCardModal .modal-content::-webkit-scrollbar-track {
    background: rgba(128,128,128,0.08);
    border-radius: 5px;
}
#taskCardModal .modal-content::-webkit-scrollbar-thumb {
    background: rgba(245,215,110,0.45);
    border-radius: 5px;
    border: 2px solid transparent;
    background-clip: padding-box;
}
#taskCardModal .modal-content::-webkit-scrollbar-thumb:hover {
    background: rgba(245,215,110,0.7);
    background-clip: padding-box;
}

/* Светлая тема */
body.trk-theme-light #taskCardModal #taskCardHead,
body.trk-theme-light #taskCardModal .modal-actions {
    background: var(--trk-modal-bg, #ffffff) !important;
    border-color: rgba(0,0,0,0.12) !important;
}
body.trk-theme-light #taskCardModal .modal-content::-webkit-scrollbar-thumb {
    background: rgba(0,137,123,0.5);
    background-clip: padding-box;
}
body.trk-theme-light #taskCardModal .modal-content::-webkit-scrollbar-thumb:hover {
    background: rgba(0,137,123,0.8);
    background-clip: padding-box;
}
